diff --git a/src/main/java/org/apache/commons/lang3/math/NumberUtils.java b/src/main/java/org/apache/commons/lang3/math/NumberUtils.java
index 1e6ccdc02..59ccff6b8 100644
--- a/src/main/java/org/apache/commons/lang3/math/NumberUtils.java
+++ b/src/main/java/org/apache/commons/lang3/math/NumberUtils.java
@@ -465,10 +465,20 @@ public class NumberUtils {
         }
         if (pfxLen > 0) { // we have a hex number
             final int hexDigits = str.length() - pfxLen;
-            if (hexDigits > 16) { // too many for Long
+            // Determine significant digit count by skipping any leading zeros after the prefix
+            int firstSig = pfxLen;
+            while (firstSig < str.length() - 1 && str.charAt(firstSig) == '0') {
+                firstSig++;
+            }
+            final int sigDigits = str.length() - firstSig;
+            final char msb = str.charAt(firstSig);
+            // A hex digit >= '8' means the high bit of that nibble is set,
+            // so a value with that many significant digits won't fit in the next-smaller signed type.
+            final boolean msbHigh = (msb >= '8' && msb <= '9') || (msb >= 'a' && msb <= 'f') || (msb >= 'A' && msb <= 'F');
+            if (sigDigits > 16 || (sigDigits == 16 && msbHigh)) { // too many for Long
                 return createBigInteger(str);
             }
-            if (hexDigits > 8) { // too many for an int
+            if (sigDigits > 8 || (sigDigits == 8 && msbHigh)) { // too many for an int
                 return createLong(str);
             }
             return createInteger(str);

